const { irissdk } = require('./import_irissdk.js')
const Iris = irissdk.Iris
const IRISGlobalNode = require('./iris_global_node.js').IRISGlobalNode

// iteration
Iris.prototype.iterator = function iterator(globalName, ...subscripts) {
  const node = new IRISGlobalNode(this, globalName, ...subscripts)
  return node[Symbol.iterator]()
}

Iris.prototype.node = function node (globalName, ...subscripts) {
  return new IRISGlobalNode(this, globalName, ...subscripts)
}


// This is to be used with functions that actually return a value
// args is an array of arguments for the function
Iris.prototype.classMethodAsync = function classMethodAsync(className, methodName, args, callback) {
  // Backward compatible implementation
  setTimeout(() => {
    try {
      const result = this.classMethodValue(className, methodName, ...args)
      callback(undefined, result)
    } catch (err) {
      callback(err)
    }
  }, 0)

}

module.exports.Iris = Iris